export interface Zielgruppe {
  slug: string; name: string; group: 'Schule & Bildung' | 'Vereine & Gemeinden' | 'Betriebe & Gewerbe' | 'Gastro & Handel' | 'Events & Privat' | 'Marken & Kreative';
  title: string; description: string; h1: string; lede: string;
  introFrage: string; // h2 über dem Antwort-Absatz: eine Frage, wie Kunden sie stellen. Nicht wie das h2 "Was wir für … drucken" formulieren.
  intro: string; // Antwort-Absatz für KI-Suche: Wer, was, wo, wie schnell
  products: string[]; benefits: { t: string; d: string }[]; faqs: { q: string; a: string }[];
  produkteText?: string; // Unterzeile zu "Was wir für … drucken", je Gruppe eigene Worte statt eines Standardsatzes
  ablaufText?: string; // Unterzeile zu "In drei Schritten zu euren Textilien", je Gruppe eigene Worte
  steps?: { t: string; d: string }[]; // drei Schritte speziell für diese Gruppe, sonst die allgemeinen
  sections?: { h: string; p: string }[]; // zusätzliche Abschnitte, z. B. Messegelände oder Trikotnummern
  keywords: string[]; image: string; imagePos?: string; imageAlt: string; topic: string;
}
